arguments.command:
curl -s -X POST https://slack.com/api/users.list -H "Content-Type: application/json" -d '{"token":"***","limit":0}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR:',d); sys.exit(1)
for u in d['members']:
    name=u.get('real_name','') or u.get('profile',{}).get('display_name','')
    if 'omar' in name.lower() or 'haddad' in name.lower():
        print(u['id'],'|',name,'| deleted:',u.get('deleted',False))
"

